/* 024_MoreCatalog.sql — generated by tools/gen-catalog.mjs: 45 tours with weekly departures, 43 hotels,
   42 flights, 46 buses and 44 taxis with 150 days of inventory. Original names and texts. Idempotent. */
SET NOCOUNT ON;
DECLARE @BU int = (SELECT TOP 1 BusinessUnitId FROM dbo.Tours ORDER BY TourId);
DECLARE @N TABLE (n int PRIMARY KEY);
INSERT @N SELECT TOP 150 ROW_NUMBER() OVER (ORDER BY (SELECT 1)) FROM sys.all_objects;
